"use strict";(self.webpackChunkkahunakv_docs=self.webpackChunkkahunakv_docs||[]).push([[8612],{3149:e=>{e.exports=JSON.parse('{"permalink":"/blog/jepsen-testing-kahuna","editUrl":"https://github.com/kahunakv.github.io/tree/tree/main/blog/2026-08-06-jepsen-testing-kahuna/index.md","source":"@site/blog/2026-08-06-jepsen-testing-kahuna/index.md","title":"Breaking Kahuna on Purpose with Jepsen","description":"Distributed systems usually look reliable when everything is healthy. The network is fast, every server is online, and requests arrive in a convenient order.","date":"2026-08-06T00:00:00.000Z","tags":[{"inline":true,"label":"kahuna","permalink":"/blog/tags/kahuna"},{"inline":true,"label":"jepsen","permalink":"/blog/tags/jepsen"},{"inline":true,"label":"testing","permalink":"/blog/tags/testing"},{"inline":true,"label":"distributed-systems","permalink":"/blog/tags/distributed-systems"}],"readingTime":10.54,"hasTruncateMarker":true,"authors":[{"name":"Andres Gutierrez","title":"Creator of Kahuna","url":"https://github.com/andresgutierrez","imageURL":"https://github.com/andresgutierrez.png","key":"andresgutierrez","page":null}],"frontMatter":{"slug":"jepsen-testing-kahuna","title":"Breaking Kahuna on Purpose with Jepsen","authors":["andresgutierrez"],"tags":["kahuna","jepsen","testing","distributed-systems"]},"unlisted":false,"nextItem":{"title":"Making Distributed Transactions Easier to Trust","permalink":"/blog/reusable-transaction-coordinator"}}')},6515:(e,s,t)=>{t.r(s),t.d(s,{assets:()=>l,contentTitle:()=>o,default:()=>d,frontMatter:()=>i,metadata:()=>n,toc:()=>h});var n=t(3149),a=t(4848),r=t(8453);const i={slug:"jepsen-testing-kahuna",title:"Breaking Kahuna on Purpose with Jepsen",authors:["andresgutierrez"],tags:["kahuna","jepsen","testing","distributed-systems"]},o="Breaking Kahuna on Purpose with Jepsen",l={authorsImageUrls:[void 0]},h=[{value:"What Is Jepsen?",id:"what-is-jepsen",level:2},{value:"Four Workloads, Four Promises",id:"four-workloads-four-promises",level:2},{value:"Key/value operations behave like one correct copy",id:"keyvalue-operations-behave-like-one-correct-copy",level:3},{value:"Locks keep owners apart and tokens moving forward",id:"locks-keep-owners-apart-and-tokens-moving-forward",level:3},{value:"Transactions behave like a safe serial order",id:"transactions-behave-like-a-safe-serial-order",level:3},{value:"Sequences never give the same value to two clients",id:"sequences-never-give-the-same-value-to-two-clients",level:3},{value:"What Does a Green Result Mean?",id:"what-does-a-green-result-mean",level:2},{value:"The Tests Have Already Helped",id:"the-tests-have-already-helped",level:2},{value:"Why It Runs Nightly",id:"why-it-runs-nightly",level:2},{value:"What Comes Next?",id:"what-comes-next",level:2},{value:"Better Confidence Starts with Better Questions",id:"better-confidence-starts-with-better-questions",level:2}];function c(e){const s={a:"a",h2:"h2",h3:"h3",li:"li",p:"p",ul:"ul",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(s.p,{children:"Distributed systems usually look reliable when everything is healthy. The network is fast, every server is online, and requests arrive in a convenient order."}),"\n",(0,a.jsx)(s.p,{children:"But what happens when a server loses contact with the rest of the cluster? What if a process stops while handling a request? What if Kahuna saves a value, but the reply never reaches the client?"}),"\n",(0,a.jsxs)(s.p,{children:["We recently added a public ",(0,a.jsx)(s.a,{href:"https://github.com/kahunakv/kahuna-jepsen",children:"Jepsen test suite for Kahuna"})," to explore these difficult situations. It creates real Kahuna clusters, sends many requests at the same time, and introduces failures on purpose. It then checks whether Kahuna still keeps its promises."]}),"\n",(0,a.jsx)(s.p,{children:"Our goal is not only to see green test results. We want to find rare problems, understand them, and make sure they do not return."}),"\n",(0,a.jsx)(s.h2,{id:"what-is-jepsen",children:"What Is Jepsen?"}),"\n",(0,a.jsxs)(s.p,{children:[(0,a.jsx)(s.a,{href:"https://github.com/jepsen-io/jepsen",children:"Jepsen"})," is a testing framework for distributed systems. It records everything that happens during a test: when each request starts, when it finishes, what result it returns, and which failures happen at the same time."]}),"\n",(0,a.jsx)(s.p,{children:"Jepsen also runs a special process called a nemesis. The name sounds dramatic, but its job is simple: create trouble. It can split the network, stop servers, pause processes, and later bring everything back."}),"\n",(0,a.jsx)(s.p,{children:"At the end, Jepsen studies the complete history and asks an important question: can all these results be explained without breaking the system's guarantees?"}),"\n",(0,a.jsx)(s.p,{children:"This is more powerful than checking HTTP status codes. Imagine that a client sends a write, Kahuna commits it, and the network loses the reply. The client sees a timeout, but the write may still exist. Jepsen keeps this uncertainty in its analysis instead of guessing that the write failed."}),"\n",(0,a.jsxs)(s.p,{children:["Our tests run against a five-node Kahuna cluster. Client requests use a different network port from the internal ",(0,a.jsx)(s.a,{href:"/docs/architecture/raft",children:"Raft communication"}),". This allows us to interrupt replication between servers while clients can still send requests and observe the results."]}),"\n",(0,a.jsx)(s.p,{children:"The nightly tests use several kinds of failure:"}),"\n",(0,a.jsxs)(s.ul,{children:["\n",(0,a.jsx)(s.li,{children:"Network partitions separate some nodes from the others."}),"\n",(0,a.jsx)(s.li,{children:"Process kills stop servers immediately."}),"\n",(0,a.jsx)(s.li,{children:"Process pauses freeze a server without closing its connections."}),"\n",(0,a.jsxs)(s.li,{children:[(0,a.jsx)(s.a,{href:"/docs/server-configuration#raft-membership-and-catch-up",children:"Membership changes"})," remove a server from the cluster and add it again as a fresh member."]}),"\n"]}),"\n",(0,a.jsx)(s.p,{children:"These situations create the timing problems that are almost impossible to reproduce with normal tests."}),"\n",(0,a.jsx)(s.h2,{id:"four-workloads-four-promises",children:"Four Workloads, Four Promises"}),"\n",(0,a.jsx)(s.p,{children:"There is no single test for all distributed-system behavior. A key/value store, a lock, a transaction, and a sequence generator each promise something different. Our suite therefore has four workloads."}),"\n",(0,a.jsx)(s.h3,{id:"keyvalue-operations-behave-like-one-correct-copy",children:"Key/value operations behave like one correct copy"}),"\n",(0,a.jsxs)(s.p,{children:["The register workload sends reads, writes, and compare-and-set operations to different nodes in Kahuna's ",(0,a.jsx)(s.a,{href:"/docs/distributed-keyvalue-store",children:"distributed key/value store"}),"."]}),"\n",(0,a.jsx)(s.p,{children:"Compare-and-set means \u201cchange the value only if it still equals the value I expect.\u201d For example, two clients may both try to change a value from 4 to 5. Only an operation based on the current value should succeed."}),"\n",(0,a.jsxs)(s.p,{children:["Jepsen uses a checker called Knossos to test each key for ",(0,a.jsx)(s.a,{href:"https://jepsen.io/consistency/models/linearizable",children:"linearizability"}),". The word is technical, but the main idea is friendly: even though many servers and clients are involved, each successful operation should look as if it happened at one exact moment on one correct copy of the data."]}),"\n",(0,a.jsx)(s.p,{children:"Real-time order also matters. If a write finishes before a new read begins, the read must not return an older value."}),"\n",(0,a.jsx)(s.p,{children:"This workload can catch an isolated server that still thinks it is the leader and returns stale data as if it were current."}),"\n",(0,a.jsx)(s.h3,{id:"locks-keep-owners-apart-and-tokens-moving-forward",children:"Locks keep owners apart and tokens moving forward"}),"\n",(0,a.jsxs)(s.p,{children:[(0,a.jsx)(s.a,{href:"/docs/distributed-locks",children:"Kahuna locks"})," use ",(0,a.jsx)(s.a,{href:"/docs/distributed-locks/leases",children:"leases"}),". A lease gives a client the lock for a limited time. If that client crashes, the lock can expire and another client can continue. Without expiration, one crashed client could block a resource forever."]}),"\n",(0,a.jsxs)(s.p,{children:["Leases also create a challenge. An old client may wake up after its lease has expired and still believe it owns the lock. Kahuna uses ",(0,a.jsx)(s.a,{href:"/docs/distributed-locks/fencing-tokens",children:"fencing tokens"})," to protect other systems from this old owner. Every new owner receives a newer token, so a database or service can reject commands carrying an older one."]}),"\n",(0,a.jsx)(s.p,{children:"The lock workload checks two promises:"}),"\n",(0,a.jsxs)(s.ul,{children:["\n",(0,a.jsx)(s.li,{children:"Two different owners must not definitely hold the same valid lease at the same time."}),"\n",(0,a.jsx)(s.li,{children:"Fencing tokens must never go backwards, and a new owner must receive a higher token."}),"\n"]}),"\n",(0,a.jsx)(s.p,{children:"The checker understands that leases expire. It does not report a problem when an overlap can be explained by normal expiration or by a release whose reply was lost."}),"\n",(0,a.jsx)(s.h3,{id:"transactions-behave-like-a-safe-serial-order",children:"Transactions behave like a safe serial order"}),"\n",(0,a.jsxs)(s.p,{children:["The transaction workload runs ",(0,a.jsx)(s.a,{href:"/docs/distributed-keyvalue-store/transactions",children:"interactive transactions"})," that read lists and append unique values across several keys."]}),"\n",(0,a.jsx)(s.p,{children:"It uses a checker called Elle. Elle studies the relationships between transactions and looks for cycles that should be impossible. In simpler terms, it asks whether the completed transactions could have run one after another in some valid order, even though they actually ran at the same time."}),"\n",(0,a.jsx)(s.p,{children:"This test can find problems that single-key checks cannot see:"}),"\n",(0,a.jsxs)(s.ul,{children:["\n",(0,a.jsx)(s.li,{children:"A lost update, where one successful write silently replaces another."}),"\n",(0,a.jsx)(s.li,{children:"An aborted read, where data from a failed transaction becomes visible."}),"\n",(0,a.jsx)(s.li,{children:"A dirty update, where a transaction builds on data that should never have committed."}),"\n",(0,a.jsx)(s.li,{children:"Write skew, where two transactions make decisions from old information and together break the expected ordering."}),"\n"]}),"\n",(0,a.jsx)(s.p,{children:"These bugs are difficult because each request may look correct by itself. The problem only becomes visible when we study the whole transaction history."}),"\n",(0,a.jsx)(s.h3,{id:"sequences-never-give-the-same-value-to-two-clients",children:"Sequences never give the same value to two clients"}),"\n",(0,a.jsxs)(s.p,{children:["Kahuna's ",(0,a.jsx)(s.a,{href:"/docs/distributed-sequencer",children:"distributed sequencer"})," can return one number or reserve a range of numbers. Clients can also retry a request with the same ",(0,a.jsx)(s.a,{href:"/docs/distributed-sequencer/idempotency",children:"idempotency key"}),". An idempotency key tells the server, \u201cthis is the same logical request again, not a new one.\u201d"]}),"\n",(0,a.jsx)(s.p,{children:"The sequencer workload checks that:"}),"\n",(0,a.jsxs)(s.ul,{children:["\n",(0,a.jsx)(s.li,{children:"Two successful allocations never contain the same value."}),"\n",(0,a.jsx)(s.li,{children:"A reserved range has the size requested by the client."}),"\n",(0,a.jsx)(s.li,{children:"Retrying with the same idempotency key returns the original allocation."}),"\n"]}),"\n",(0,a.jsx)(s.p,{children:"The test allows gaps and values that arrive out of order. This is intentional. Kahuna gives nodes blocks of values that they can allocate quickly. A leader change may leave part of a block unused, creating a gap. That is safe because the important promise is uniqueness, not a perfect sequence with no missing numbers."}),"\n",(0,a.jsx)(s.h2,{id:"what-does-a-green-result-mean",children:"What Does a Green Result Mean?"}),"\n",(0,a.jsx)(s.p,{children:"A green Jepsen result is strong evidence, but it is not a mathematical proof that every possible execution is correct."}),"\n",(0,a.jsx)(s.p,{children:"It means that, for the requests, load, configuration, duration, and failures in that run, the checker found no broken guarantee. Another timing pattern may still reveal a rare bug. This is why we repeat tests with different request rates and shorter or longer periods between failures."}),"\n",(0,a.jsx)(s.p,{children:"We also need to test the testers. During this work, our lock checker reported mutual-exclusion problems that did not really happen. It extended a client's lock period after a release reply was lost. We corrected the logic and added small test histories with known good and bad results. These negative controls prove that the checker can still detect a real violation."}),"\n",(0,a.jsx)(s.p,{children:"An empty test is not a successful test either. If no transaction commits, there is nothing useful to analyze. If the sequencer returns too few values, its result is unknown. If the linearizability checker runs out of memory before it finishes, that result is also unknown\u2014not green."}),"\n",(0,a.jsx)(s.p,{children:"Being honest about these limits is an important part of reliable testing."}),"\n",(0,a.jsx)(s.h2,{id:"the-tests-have-already-helped",children:"The Tests Have Already Helped"}),"\n",(0,a.jsx)(s.p,{children:"The new suite started finding useful problems almost immediately."}),"\n",(0,a.jsx)(s.p,{children:"The key/value workload found stale reads from a node that was separated from the majority. The node refused writes because it could not replicate them, which was correct. However, it still returned old values for reads as normal successful responses. Kahuna now confirms its leadership with the cluster before serving this kind of local read."}),"\n",(0,a.jsx)(s.p,{children:"The lock workload found fencing tokens moving backwards after leader changes. One issue involved committed data during a restart. Another involved a new leader reading state before pending storage work was fully available. These failures needed a specific combination of timing and leadership changes, which made them difficult to find with ordinary tests."}),"\n",(0,a.jsx)(s.p,{children:"The transaction workload found lost updates and data from aborted transactions becoming visible. It also found write skew in a mode where read validation should stop it. These investigations improved how Kahuna validates read-modify-write operations and how it records the final result when commit and rollback compete."}),"\n",(0,a.jsx)(s.p,{children:"Jepsen also found less obvious problems. Some temporary network failures escaped as HTTP 500 responses instead of asking the client to retry. Some runs looked clean only because no useful operation finished. We even found a bug in our own lock checker."}),"\n",(0,a.jsx)(s.p,{children:"Finding a checker bug is not wasted time. The test suite is software too, and we must verify its assumptions with the same care that we apply to Kahuna."}),"\n",(0,a.jsx)(s.p,{children:"Every run keeps its history, timeline, latency charts, result details, and server logs. This gives us evidence that connects a visible failure to a particular event in the cluster. It is much more useful than a message that only says \u201cthe test failed.\u201d"}),"\n",(0,a.jsx)(s.h2,{id:"why-it-runs-nightly",children:"Why It Runs Nightly"}),"\n",(0,a.jsx)(s.p,{children:"The Jepsen suite runs every night and can also be started manually against a selected version of Kahuna. Different jobs combine the four workloads with different failures. Membership testing runs for longer because removing and safely adding a cluster member can take one or two minutes."}),"\n",(0,a.jsx)(s.p,{children:"We do not plan to make Jepsen a required check for every pull request. These tests are expensive and intentionally unpredictable. A slow shared runner can create extra timeouts and a history that is too large to analyze. A noisy required check soon becomes a check that everybody ignores."}),"\n",(0,a.jsxs)(s.p,{children:["A failed nightly run asks us to download the artifacts and investigate. A clean run adds more confidence. Neither one replaces unit tests, focused regression tests, code review, or ",(0,a.jsx)(s.a,{href:"/docs/benchmarking",children:"performance benchmarks"}),"."]}),"\n",(0,a.jsx)(s.h2,{id:"what-comes-next",children:"What Comes Next?"}),"\n",(0,a.jsxs)(s.p,{children:["The next major workload will focus on ",(0,a.jsx)(s.a,{href:"/docs/distributed-keyvalue-store/snapshot-holds",children:"snapshot reads and snapshot holds"}),". A snapshot lets a transaction read data as it existed at an earlier logical time, while new writes continue in the cluster. We want to verify that the old view stays stable and that snapshot holds protect the required ",(0,a.jsx)(s.a,{href:"/docs/internals/mvcc",children:"MVCC history"})," correctly."]}),"\n",(0,a.jsxs)(s.p,{children:["Clock faults are another important area. Kahuna uses ",(0,a.jsx)(s.a,{href:"/docs/architecture/hybrid-logical-clocks",children:"hybrid logical clocks"})," for snapshots and lock leases. Moving time inside Docker Desktop can affect the whole virtual machine, so we will run these experiments on disposable Linux hosts where the clock changes are isolated."]}),"\n",(0,a.jsxs)(s.p,{children:["We have also added a recovery checker. It measures the time between the end of a failure and the first successful request, adding another view of Kahuna's ",(0,a.jsx)(s.a,{href:"/docs/internals/replication",children:"replication and recovery behavior"}),". This helps us separate two questions:"]}),"\n",(0,a.jsxs)(s.ul,{children:["\n",(0,a.jsx)(s.li,{children:"Is the cluster returning incorrect results?"}),"\n",(0,a.jsx)(s.li,{children:"Is the cluster correct but taking too long to become available again?"}),"\n"]}),"\n",(0,a.jsx)(s.p,{children:"We need more recovery data from runs where transactions make no progress. This will show whether the failure schedule is faster than normal recovery or whether the cluster sometimes gets stuck while finding a leader."}),"\n",(0,a.jsx)(s.p,{children:"Other follow-up work includes handling one remaining retryable HTTP/2 error correctly, gathering more evidence for the new sequencer workload, testing membership changes with more workloads, and trying different levels of load and fault timing."}),"\n",(0,a.jsx)(s.p,{children:"When Jepsen discovers a bug, we also want to create a smaller and more predictable regression test whenever possible. Jepsen is excellent at finding a surprising order of events. A focused test is better for checking that the same bug never returns."}),"\n",(0,a.jsx)(s.h2,{id:"better-confidence-starts-with-better-questions",children:"Better Confidence Starts with Better Questions"}),"\n",(0,a.jsx)(s.p,{children:"Jepsen does not make Kahuna correct on its own. It helps us ask better questions:"}),"\n",(0,a.jsxs)(s.ul,{children:["\n",(0,a.jsx)(s.li,{children:"Can an isolated leader return old data as current?"}),"\n",(0,a.jsx)(s.li,{children:"Can a fencing token move backwards after a restart?"}),"\n",(0,a.jsx)(s.li,{children:"Can two transactions commit when no safe order can explain both?"}),"\n",(0,a.jsx)(s.li,{children:"Can a sequence value be returned twice after a lost reply?"}),"\n",(0,a.jsx)(s.li,{children:"How long does the cluster need to recover after a failure?"}),"\n"]}),"\n",(0,a.jsx)(s.p,{children:"These questions tell us much more than \u201cdid the servers stay online?\u201d"}),"\n",(0,a.jsx)(s.p,{children:"Kahuna is a coordination system, so its behavior during uncertainty is essential. By breaking the cluster on purpose and carefully checking what happened, we can turn difficult failure scenarios into useful evidence\u2014and use that evidence to keep improving Kahuna."})]})}function d(e={}){const{wrapper:s}={...(0,r.R)(),...e.components};return s?(0,a.jsx)(s,{...e,children:(0,a.jsx)(c,{...e})}):c(e)}},8453:(e,s,t)=>{t.d(s,{R:()=>i,x:()=>o});var n=t(6540);const a={},r=n.createContext(a);function i(e){const s=n.useContext(r);return n.useMemo((function(){return"function"==typeof e?e(s):{...s,...e}}),[s,e])}function o(e){let s;return s=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),n.createElement(r.Provider,{value:s},e.children)}}}]);